const STORAGE_KEY = 'airwayLabProgress_v1';
let progress = loadProgress();
let currentView = 'homeView';
let studyQueue = [];
let studyIndex = 0;
let showingAnswer = false;
let studyAllMode = false;
let currentStudyTopic = 'all';
let currentLibraryTopic = 'roles';
let currentQuiz = [];
let quizIndex = 0;
let quizScore = 0;
let quizAnswers = [];
let quizCount = 10;
let answeredCurrent = false;
let toastTimer;

function loadProgress(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||{cards:{},lastScore:null,tests:0,dark:false};}catch(e){return {cards:{},lastScore:null,tests:0,dark:false};}}
function saveProgress(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(progress));const s=document.getElementById('saveIndicator');if(s){s.innerHTML='<i></i> נשמר במכשיר';}}catch(e){showToast('לא ניתן לשמור במכשיר הזה. אפשר להמשיך ללמוד, אך ההתקדמות לא תישמר.');}}

function migrateExamSchedule(){
  // Previous versions used day/week intervals. For this exam-eve build, make every
  // previously scheduled future card available once and reset its old day-based stage.
  const version='exam-eve-minutes-v1';
  if(progress.scheduleVersion===version)return;
  const now=Date.now();
  Object.values(progress.cards||{}).forEach(card=>{
    if(!card||typeof card!=='object')return;
    if(card.due && new Date(card.due).getTime()>now)card.due=new Date(now).toISOString();
    card.stage=0;
  });
  progress.scheduleVersion=version;
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(progress));}catch(e){}
}

function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function topicTitle(id){return TOPICS.find(t=>t.id===id)?.title||'כל הנושאים';}
function showToast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300);}
function gotoView(id){if(!document.getElementById(id))return;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.goto===id));currentView=id;window.scrollTo({top:0,behavior:'smooth'});if(id==='homeView')updateHome();if(id==='libraryView')renderLibrary();if(id==='studyView'&&!studyQueue.length)startStudy(currentStudyTopic);}
function dueDate(card){const p=progress.cards[card.id];return p?.due?new Date(p.due):null;}
function isDue(card){const p=progress.cards[card.id];return !p||!p.due||new Date(p.due)<=new Date();}
function updateHome(){const due=CARDS.filter(isDue).length;const learned=Object.keys(progress.cards).filter(id=>CARDS.some(c=>c.id===id)).length;document.getElementById('dueCount').textContent=due;document.getElementById('learnedCount').textContent=learned+'/'+CARDS.length;document.getElementById('bestScore').textContent=progress.lastScore===null?'—':progress.lastScore+'%';document.getElementById('todayLabel').textContent=new Intl.DateTimeFormat('he-IL',{weekday:'long',day:'numeric',month:'long'}).format(new Date());}
function populateTopics(){['studyTopic','quizTopic'].forEach(id=>{const sel=document.getElementById(id);TOPICS.forEach(t=>{const o=document.createElement('option');o.value=t.id;o.textContent=t.title;sel.appendChild(o);});});const grid=document.getElementById('topicGrid');grid.innerHTML=TOPICS.map(t=>`<button class="topic-card" data-topic="${t.id}" type="button"><span class="topic-number">${t.n} / 07</span><span class="topic-emoji">${t.icon}</span><strong>${esc(t.title)}</strong><small>${esc(t.short)}</small><span class="topic-arrow">←</span></button>`).join('');grid.querySelectorAll('[data-topic]').forEach(btn=>btn.addEventListener('click',()=>{currentStudyTopic=btn.dataset.topic;document.getElementById('studyTopic').value=currentStudyTopic;startStudy(currentStudyTopic);gotoView('studyView');}));}
function startStudy(topic='all',all=false){currentStudyTopic=topic;studyAllMode=all;studyIndex=0;showingAnswer=false;let list=CARDS.filter(c=>(topic==='all'||c.topic===topic)&&(all||isDue(c)));if(!all){list=list.slice(0,15);}studyQueue=list;renderStudy();}
function renderStudy(){const empty=document.getElementById('studyEmpty'),wrap=document.getElementById('flashcardWrap'),actions=document.getElementById('ratingActions');if(studyIndex>=studyQueue.length){wrap.hidden=true;actions.hidden=true;empty.hidden=false;document.getElementById('sessionCount').textContent='הסתיים';document.getElementById('studyProgressText').textContent=`${studyQueue.length} / ${studyQueue.length}`;document.getElementById('studyProgressFill').style.width='100%';return;}empty.hidden=true;wrap.hidden=false;actions.hidden=true;const c=studyQueue[studyIndex];showingAnswer=false;document.getElementById('cardTopic').textContent=topicTitle(c.topic);document.getElementById('cardIndex').textContent=String(studyIndex+1).padStart(2,'0');document.getElementById('cardQuestion').textContent=c.q;document.getElementById('cardAnswerText').textContent=c.a;const note=document.getElementById('cardNote');note.textContent=c.note;note.hidden=!c.note;document.getElementById('cardAnswer').hidden=true;document.getElementById('flipHint').textContent='אין צורך למהר — תני למוח לנסות.';document.getElementById('revealBtn').hidden=false;document.getElementById('sessionCount').textContent=`${studyQueue.length} כרטיסיות בסשן`;document.getElementById('studyProgressText').textContent=`${studyIndex+1} / ${studyQueue.length}`;document.getElementById('studyProgressFill').style.width=`${studyIndex/studyQueue.length*100}%`;}
function revealCard(){if(showingAnswer)return;showingAnswer=true;document.getElementById('cardAnswer').hidden=false;document.getElementById('ratingActions').hidden=false;document.getElementById('revealBtn').hidden=true;document.getElementById('flipHint').textContent='דרגי לפי מה שהצלחת לשלוף, לא לפי מה שנראה מוכר.';}
function rateCard(type){const c=studyQueue[studyIndex];const old=progress.cards[c.id]||{stage:0,seen:0,wrong:0};let stage=old.stage||0;const due=new Date();if(type==='again'){stage=0;old.wrong=(old.wrong||0)+1;due.setMinutes(due.getMinutes()+3);}else if(type==='hard'){stage=0;due.setMinutes(due.getMinutes()+15);}else{stage=Math.min(stage+1,5);const minutes=[45,90,180,360,600][Math.max(0,stage-1)];due.setMinutes(due.getMinutes()+minutes);}progress.cards[c.id]={stage,seen:(old.seen||0)+1,wrong:old.wrong||0,due:due.toISOString(),last:Date.now()};saveProgress();studyIndex++;renderStudy();updateHome();}
function beginQuiz(){const topic=document.getElementById('quizTopic').value;let pool=QUESTIONS.filter(x=>topic==='all'||x.topic===topic);pool=shuffle(pool);const count=quizCount==='all'?pool.length:Math.min(Number(quizCount),pool.length);currentQuiz=pool.slice(0,count);quizIndex=0;quizScore=0;quizAnswers=[];answeredCurrent=false;document.getElementById('quizSetup').hidden=true;document.getElementById('quizResults').hidden=true;document.getElementById('quizStage').hidden=false;renderQuestion();}
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function renderQuestion(){const qn=currentQuiz[quizIndex];answeredCurrent=false;document.getElementById('quizTopicLabel').textContent=topicTitle(qn.topic);document.getElementById('quizQuestionNo').textContent=`שאלה ${quizIndex+1} מתוך ${currentQuiz.length}`;document.getElementById('quizProgressFill').style.width=`${quizIndex/currentQuiz.length*100}%`;document.getElementById('quizQuestionText').textContent=qn.question;document.getElementById('answersList').innerHTML=qn.options.map((o,i)=>`<button class="answer-option" data-answer="${i}" type="button"><span class="option-letter">${'אבגד'[i]||i+1}</span><span>${esc(o)}</span></button>`).join('');document.getElementById('feedbackPanel').hidden=true;document.getElementById('nextQuestionBtn').disabled=true;document.getElementById('nextQuestionBtn').textContent=quizIndex===currentQuiz.length-1?'לתוצאות ←':'השאלה הבאה ←';document.getElementById('quizScoreLive').textContent=`נכונות: ${quizScore}`;document.querySelectorAll('.answer-option').forEach(btn=>btn.addEventListener('click',()=>answerQuestion(Number(btn.dataset.answer))));}
function answerQuestion(choice){if(answeredCurrent)return;answeredCurrent=true;const qn=currentQuiz[quizIndex];const correct=choice===qn.correct;if(correct)quizScore++;quizAnswers.push({topic:qn.topic,correct,question:qn.question});document.querySelectorAll('.answer-option').forEach((btn,i)=>{btn.disabled=true;if(i===qn.correct)btn.classList.add('correct');if(i===choice&&!correct)btn.classList.add('incorrect');});const feedback=document.getElementById('feedbackPanel');feedback.hidden=false;feedback.className='feedback-panel '+(correct?'is-correct':'is-wrong');feedback.innerHTML=`<strong>${correct?'נכון מאוד ✓':'לא הפעם — ממשיכים ללמוד'}</strong>${esc(qn.explanation)}`;document.getElementById('quizScoreLive').textContent=`נכונות: ${quizScore}`;document.getElementById('nextQuestionBtn').disabled=false;}
function showQuizResults(){document.getElementById('quizStage').hidden=true;const results=document.getElementById('quizResults');results.hidden=false;const pct=Math.round(quizScore/currentQuiz.length*100);progress.lastScore=pct;progress.tests=(progress.tests||0)+1;saveProgress();const byTopic={};quizAnswers.forEach(a=>{byTopic[a.topic]??={right:0,total:0};byTopic[a.topic].total++;if(a.correct)byTopic[a.topic].right++;});const weak=Object.entries(byTopic).filter(([k,v])=>v.right<v.total).sort((a,b)=>(a[1].right/a[1].total)-(b[1].right/b[1].total));results.innerHTML=`<div class="result-score">${pct}%</div><h2>${pct>=90?'שליטה יפה!':pct>=70?'כיוון טוב — ממשיכים לחזק':'זה בדיוק מה שתרגול נועד לגלות'}</h2><p>ענית נכון על ${quizScore} מתוך ${currentQuiz.length} שאלות.</p><div class="result-topics"><h3>איפה כדאי לחזק?</h3>${weak.length?weak.map(([id,v])=>`<p><strong>${esc(topicTitle(id))}:</strong> ${v.right}/${v.total} נכונות — מומלץ לתרגל כרטיסיות בנושא.</p>`).join(''):'<p>ענית נכון על כל השאלות בסשן הזה. נסי מבחן מעורב נוסף בעוד זמן מה.</p>'}</div><div class="result-buttons"><button class="primary-btn" id="retryQuizBtn" type="button">מבחן נוסף ←</button><button class="quiet-btn" id="reviewWeakBtn" type="button">תרגול נושא לחיזוק</button></div>`;document.getElementById('retryQuizBtn').addEventListener('click',()=>{document.getElementById('quizSetup').hidden=false;results.hidden=true;});document.getElementById('reviewWeakBtn').addEventListener('click',()=>{const topic=weak[0]?.[0]||'all';currentStudyTopic=topic;document.getElementById('studyTopic').value=topic;startStudy(topic,true);gotoView('studyView');});updateHome();}
function nextQuestion(){if(quizIndex<currentQuiz.length-1){quizIndex++;renderQuestion();}else showQuizResults();}
function renderLibraryNav(){const nav=document.getElementById('libraryNav');nav.innerHTML=TOPICS.map(t=>`<button type="button" data-library-topic="${t.id}" class="${t.id===currentLibraryTopic?'active':''}">${t.n}. ${esc(t.title)}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{currentLibraryTopic=b.dataset.libraryTopic;renderLibrary();}));}
function renderLibrary(){renderLibraryNav();const search=(document.getElementById('librarySearch')?.value||'').trim().toLowerCase();const content=document.getElementById('libraryContent');let entries=Object.entries(SUMMARIES).filter(([id])=>!search||JSON.stringify(SUMMARIES[id]).toLowerCase().includes(search)||CARDS.some(c=>c.topic===id&&(c.q+' '+c.a+' '+c.note).toLowerCase().includes(search)));if(search){content.innerHTML=entries.length?entries.map(([id,s])=>summaryHTML(id,s,true)).join(''):`<div class="summary-card"><h2>לא נמצאו תוצאות</h2><p>נסי מונח אחר או קיצור כמו OPA, LMA, ETCO₂.</p></div>`;return;}const item=SUMMARIES[currentLibraryTopic];content.innerHTML=summaryHTML(currentLibraryTopic,item,false);}
function summaryHTML(id,s,compact){return `<article class="summary-card"><p class="eyebrow">${esc(topicTitle(id))}</p><h2>${esc(s.title)}</h2><p>${esc(s.lead)}</p>${s.sections.map(([h,items])=>`<h3>${esc(h)}</h3><ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}<div class="keyline"><strong>משפט מפתח:</strong> ${esc(s.key)}</div>${compact?`<button class="text-btn" type="button" data-learn-topic="${id}">תרגול כרטיסיות בנושא ←</button>`:`<button class="text-btn" type="button" data-learn-topic="${id}">תרגול כרטיסיות בנושא ←</button>`}</article>`;}
function renderAccuracy(){document.getElementById('accuracyList').innerHTML=ACCURACY.map((a,i)=>`<article class="accuracy-item"><span class="flag">!</span><div><h3>${esc(a[0])}</h3><p>${esc(a[1])}</p><div class="check-status">מה לעשות: ${esc(a[2])}</div></div></article>`).join('');}
function init(){migrateExamSchedule();populateTopics();renderAccuracy();updateHome();
  // Exam-eve checklist is independent from flashcard progress and persists locally.
  const cramState=(()=>{try{return JSON.parse(localStorage.getItem('airwayLabCram_v1'))||{};}catch(e){return {};}})();
  document.querySelectorAll('[data-cram]').forEach(box=>{const key=box.dataset.cram;box.checked=!!cramState[key];box.closest('.cram-step')?.classList.toggle('done',box.checked);box.addEventListener('change',()=>{cramState[key]=box.checked;try{localStorage.setItem('airwayLabCram_v1',JSON.stringify(cramState));}catch(e){}box.closest('.cram-step')?.classList.toggle('done',box.checked);});});
  document.getElementById('cramCardsBtn')?.addEventListener('click',()=>{currentStudyTopic='all';document.getElementById('studyTopic').value='all';startStudy('all',true);gotoView('studyView');});
  document.getElementById('cramQuizBtn')?.addEventListener('click',()=>{quizCount=20;document.querySelectorAll('#quizLength .choice-pill').forEach(x=>x.classList.toggle('active',x.dataset.count==='20'));document.getElementById('quizTopic').value='all';beginQuiz();gotoView('quizView');});
document.getElementById('todayLabel').textContent=new Intl.DateTimeFormat('he-IL',{weekday:'long',day:'numeric',month:'long'}).format(new Date());document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>gotoView(b.dataset.goto)));document.getElementById('startStudyBtn').addEventListener('click',()=>{startStudy('all');gotoView('studyView');});document.getElementById('revealBtn').addEventListener('click',revealCard);document.querySelectorAll('[data-rating]').forEach(b=>b.addEventListener('click',()=>rateCard(b.dataset.rating)));document.getElementById('studyTopic').addEventListener('change',e=>startStudy(e.target.value));document.getElementById('showAllCardsBtn').addEventListener('click',()=>startStudy(currentStudyTopic,true));document.getElementById('beginQuizBtn').addEventListener('click',beginQuiz);document.querySelectorAll('#quizLength [data-count]').forEach(b=>b.addEventListener('click',()=>{quizCount=b.dataset.count;document.querySelectorAll('#quizLength .choice-pill').forEach(x=>x.classList.toggle('active',x===b));}));document.getElementById('nextQuestionBtn').addEventListener('click',nextQuestion);document.getElementById('librarySearch').addEventListener('input',renderLibrary);document.getElementById('libraryContent').addEventListener('click',e=>{const b=e.target.closest('[data-learn-topic]');if(b){const topic=b.dataset.learnTopic;currentStudyTopic=topic;document.getElementById('studyTopic').value=topic;startStudy(topic,true);gotoView('studyView');}});document.getElementById('themeToggle').addEventListener('click',()=>{document.body.classList.toggle('dark');progress.dark=document.body.classList.contains('dark');saveProgress();});if(progress.dark)document.body.classList.add('dark');document.getElementById('resetProgressBtn').addEventListener('click',()=>{if(confirm('לאפס את כל הכרטיסיות, התוצאות וההתקדמות שנשמרו במכשיר?')){progress={cards:{},lastScore:null,tests:0,dark:document.body.classList.contains('dark')};saveProgress();updateHome();if(currentView==='studyView')startStudy(currentStudyTopic);showToast('ההתקדמות אופסה. מתחילים מחדש!');}});renderLibrary();document.addEventListener('keydown',e=>{if(currentView==='studyView'&&e.code==='Space'&&e.target.tagName!=='BUTTON'&&e.target.tagName!=='SELECT'){e.preventDefault();if(showingAnswer){rateCard('hard');}else revealCard();}});}
init();
if ('serviceWorker' in navigator && location.protocol.startsWith('http')) {
  window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').catch(() => {}));
}
